  datatype Action = Register(user: string, event: string)

  ghost predicate Inv(m: Model) {
    var (registrations, confirmed) := m;
    forall u | u in confirmed :: 
      exists e | e in registrations[u] :: true
  }

  function Init(): Model {
    (map[], set[])
